using Neemle.CSharpComposer.Model;
using Neemle.CSharpComposer.Rendering;
using static Neemle.CSharpComposer.Tests.Scenarios.Build;

namespace Neemle.CSharpComposer.Tests.Scenarios;

// Switch-section fall-through analysis, member language features, modifier rules and graph checks.
public static class FlowFeatureScenarios
{
    static CsExpression Id => Cs.Id("a");

    static CsStatement Run => Cs.Statement(Cs.Call(Cs.Id("Run")));

    // A first section with the given body, then a default section that breaks.
    static CsDocument Section(CsBody body) => InMethod(Cs.Switch(Id, Cs.Section(body, Cs.Case(Cs.Literal(1))), Cs.Section(Cs.Body(Cs.Break()), Cs.Default())));

    static CsDocument Section(params CsStatement[] statements) => Section(Cs.Body(statements));

    static CsStatement Loop(StatementKind kind, CsExpression? condition, params CsStatement[] body) => new(kind, condition) { Body = Cs.Body(body) };

    static CsDocument Old(CsMember member, CsLanguageVersion version, TypeKind parent = TypeKind.Class) => InType(parent, member).At(version);

    static CsMethod M(params string[] modifiers) => new(Cs.Void, "M") { Modifiers = modifiers, Body = Cs.Body() };

    public static IEnumerable<Scenario> All()
    {
        // Fall-through analysis of a switch section.
        yield return new("flow.raw-body", () => Section(Cs.RawBody("break;")), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                break;\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.tree-body", () => Section(new CsBody { Tree = Cs.ParseTree("Run(); return;").Root }), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                Run();\n                return;\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.tree-body-falls", () => Section(new CsBody { Tree = Cs.ParseTree("Run();").Root }), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.tree-body-invalid", () => Section(new CsBody { Tree = new CsTree(new CsNode[] { new CsSymbol(null, new CsSymbolOptions()) }) }), "invalid: SYM001 A symbol must be a reference, value, operation, declaration or compound.");
        yield return new("flow.after-return", () => Section(Cs.Return(), Run), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                return;\n                Run();\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.null-statement", () => Section(Run, null!), "invalid: GEN002 Required node or collection is null.");
        yield return new("flow.deep", () =>
        {
            CsStatement statement = Cs.Break();
            for (int i = 0; i < 70; i++) statement = Cs.Block(statement);
            return Section(statement);
        }, "invalid: GEN001 Node graph exceeds128 or contains a cycle.");
        yield return new("flow.labeled-break", () => Section(new CsStatement(StatementKind.Break, Text: "l")), "invalid: GEN092 Named jump requires an enclosing labeled loop or switch; continue requires a loop.");
        yield return new("flow.labeled-continue", () => Section(new CsStatement(StatementKind.Continue, Text: "l")), "invalid: GEN092 Named jump requires an enclosing labeled loop or switch; continue requires a loop.");
        yield return new("flow.continue", () => InMethod(Loop(StatementKind.While, Cs.Literal(true), Cs.Switch(Id, Cs.Section(Cs.Body(Cs.Continue()), Cs.Default())))), "class C\n{\n    void M()\n    {\n        while (true)\n        {\n            switch (a)\n            {\n                default:\n                    continue;\n            }\n        }\n    }\n}\n");
        yield return new("flow.raw-statement", () => Section(Cs.RawStatement("break;")), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                break;\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.nested-switch", () => Section(Cs.Switch(Id, Cs.Section(Cs.Body(Cs.Break()), Cs.Default()))), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                switch (a)\n                {\n                    default:\n                        break;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.goto-yield", () => Section(new CsStatement(StatementKind.Goto, Text: "l")), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                goto l;\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.lock", () => Section(new CsStatement(StatementKind.Lock, Id) { Body = Cs.Body(Cs.Return()) }), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                lock (a)\n                {\n                    return;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.if-true", () => Section(Cs.If(Cs.Literal(true), Cs.Body(Cs.Return()))), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                if (true)\n                {\n                    return;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.if-false", () => Section(Cs.If(Cs.Literal(false), Cs.Body(Run), Cs.Block(Cs.Return()))), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                if (false)\n                {\n                    Run();\n                }\n                else\n                {\n                    return;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.if-both", () => Section(Cs.If(Id, Cs.Body(Cs.Return()), Cs.Block(Cs.Throw(Id)))), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                if (a)\n                {\n                    return;\n                }\n                else\n                {\n                    throw a;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.if-one", () => Section(Cs.If(Id, Cs.Body(Cs.Return()))), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.try-catch", () => Section(Cs.Try(Cs.Body(Cs.Return()), new[] { Cs.CatchAll(Cs.Body(Cs.Return())) })), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                try\n                {\n                    return;\n                }\n                catch\n                {\n                    return;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.try-catch-falls", () => Section(Cs.Try(Cs.Body(Cs.Return()), new[] { Cs.CatchAll(Cs.Body()) })), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.try-catches-null", () => Section(Cs.Try(Cs.Body(Cs.Return()), null, Cs.Body()) with { Catches = null! }), "invalid: GEN002 Required node or collection is null.");
        yield return new("flow.try-null-handler", () => Section(Cs.Try(Cs.Body(Cs.Return()), new CsCatch[] { null! })), "invalid: GEN002 Required node or collection is null.");
        yield return new("flow.try-finally-returns", () => Section(Cs.Try(Cs.Body(), null, Cs.Body(Cs.Return()))), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                try\n                {\n                }\n                finally\n                {\n                    return;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.try-finally", () => Section(Cs.Try(Cs.Body(Cs.Return()), null, Cs.Body())), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                try\n                {\n                    return;\n                }\n                finally\n                {\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.while-false", () => Section(Loop(StatementKind.While, Cs.Literal(false), Cs.Break())), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.while-true-return", () => Section(Loop(StatementKind.While, Cs.Literal(true), Cs.Return())), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                while (true)\n                {\n                    return;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.while-true-break", () => Section(Loop(StatementKind.While, Cs.Literal(true), Cs.Break())), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.while-condition", () => Section(Loop(StatementKind.While, Id, Cs.Return())), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.for-forever", () => Section(Cs.For(Cs.Body(Cs.Return()))), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                for (; ; )\n                {\n                    return;\n                }\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.foreach", () => Section(Cs.ForEach("x", Id, Cs.Body(Cs.Return()))), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.do-return", () => Section(Cs.DoWhile(Cs.Body(Cs.Return()), Id)), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                do\n                {\n                    return;\n                }\n                while (a);\n            default:\n                break;\n        }\n    }\n}\n");
        yield return new("flow.do-falls", () => Section(Cs.DoWhile(Cs.Body(Run), Id)), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.do-continue", () => Section(Cs.DoWhile(Cs.Body(Cs.If(Id, Cs.Body(Cs.Continue())), Cs.Return()), Id)), "invalid: GEN081 A switch section cannot fall through; use break, return, throw or goto.");
        yield return new("flow.do-forever", () => Section(Cs.DoWhile(Cs.Body(Run), Cs.Literal(true))), "class C\n{\n    void M()\n    {\n        switch (a)\n        {\n            case 1:\n                do\n                {\n                    Run();\n                }\n                while (true);\n            default:\n                break;\n        }\n    }\n}\n");

        // Member language features.
        yield return new("feature.safe", () => Old(M("safe"), CsLanguageVersion.CSharp15), "invalid: GEN073 Memory safety contract requires C# preview.");
        yield return new("feature.partial-property-old", () => Old(new CsProperty(Cs.Int, "P") { Modifiers = new[] { "partial" }, Accessors = new[] { new CsAccessor("get") } }, CsLanguageVersion.CSharp12), "invalid: GEN073 Partial property/indexer requires C# 13.");
        yield return new("feature.partial-event-old", () => Old(new CsEvent("System.Action", "E") { Modifiers = new[] { "partial" } }, CsLanguageVersion.CSharp13), "invalid: GEN073 Partial event/constructor requires C# 14.");
        yield return new("feature.partial-constructor-old", () => Old(new CsConstructor("C") { Modifiers = new[] { "partial" }, Body = null }, CsLanguageVersion.CSharp13), "invalid: GEN073 Partial event/constructor requires C# 14.");
        yield return new("feature.required-old", () => Old(new CsProperty(Cs.Int, "P") { Modifiers = new[] { "required" }, Accessors = new[] { new CsAccessor("get"), new CsAccessor("set") } }, CsLanguageVersion.CSharp10), "invalid: GEN073 Required member requires C# 11.");
        yield return new("feature.record-old", () => new CsDocument(CsLanguageVersion.CSharp8) { Types = new[] { new CsTypeDeclaration(TypeKind.Record, "R") } }, "invalid: GEN073 Record class requires C# 9.");
        yield return new("feature.ref-struct-interfaces-old", () => new CsDocument(CsLanguageVersion.CSharp12) { Types = new[] { new CsTypeDeclaration(TypeKind.Struct, "S") { Modifiers = new[] { "ref" }, BaseTypes = new[] { Cs.Type("I") } } } }, "invalid: GEN073 Ref struct interfaces requires C# 13.");
        yield return new("feature.ref-struct-base-null", () => new CsDocument(CsLanguageVersion.CSharp12) { Types = new[] { new CsTypeDeclaration(TypeKind.Struct, "S") { Modifiers = new[] { "ref" }, BaseTypes = null! } } }, "invalid: GEN002 Required node or collection is null.");
        yield return new("feature.readonly-member-old", () => Old(M("readonly"), CsLanguageVersion.CSharp7_3, TypeKind.Struct), "invalid: GEN073 Readonly member requires C# 8.");
        yield return new("feature.partial-public-old", () => Old(new CsMethod(Cs.Void, "M") { Modifiers = new[] { "public", "partial" } }, CsLanguageVersion.CSharp8), "invalid: GEN073 Enhanced partial method requires C# 9.");
        yield return new("feature.partial-returns-old", () => Old(new CsMethod(Cs.Int, "M") { Modifiers = new[] { "partial" } }, CsLanguageVersion.CSharp8), "invalid: GEN073 Enhanced partial method requires C# 9.");
        yield return new("feature.partial-raw-return", () => Old(new CsMethod(Cs.RawType("int"), "M") { Modifiers = new[] { "partial" } }, CsLanguageVersion.CSharp9), "class C\n{\n    partial int M();\n}\n");
        yield return new("feature.partial-out-old", () => Old(new CsMethod(Cs.Void, "M") { Modifiers = new[] { "partial" }, Parameters = new[] { new CsParameter(Cs.Int, "x") { Modifier = "out" } } }, CsLanguageVersion.CSharp8), "invalid: GEN073 Enhanced partial method requires C# 9.");
        yield return new("feature.partial-parameters-null", () => Old(new CsMethod(Cs.Void, "M") { Modifiers = new[] { "partial" }, Parameters = null! }, CsLanguageVersion.CSharp8), "invalid: GEN002 Required node or collection is null.");
        yield return new("feature.partial-null-parameter", () => Old(new CsMethod(Cs.Void, "M") { Modifiers = new[] { "partial" }, Parameters = new CsParameter[] { null! } }, CsLanguageVersion.CSharp8), "invalid: GEN002 Required node or collection is null.");
        yield return new("feature.partial-plain", () => Old(new CsMethod(Cs.Void, "M") { Modifiers = new[] { "partial" }, Parameters = new[] { new CsParameter(Cs.Int, "x") } }, CsLanguageVersion.CSharp8), "class C\n{\n    partial void M(int x);\n}\n");
        yield return new("feature.interface-property-expression-old", () => Old(new CsProperty(Cs.Int, "P") { Expression = Cs.Literal(1) }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "invalid: GEN073 Implemented/private/static interface member requires C# 8.");
        yield return new("feature.interface-property-body-old", () => Old(new CsProperty(Cs.Int, "P") { Accessors = new[] { new CsAccessor("get") { Body = Cs.Body(Cs.Return(Cs.Literal(1))) } } }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "invalid: GEN073 Implemented/private/static interface member requires C# 8.");
        yield return new("feature.interface-property-abstract", () => Old(new CsProperty(Cs.Int, "P") { Accessors = new[] { new CsAccessor("get") } }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "interface C\n{\n    int P { get; }\n}\n");
        yield return new("feature.interface-property-accessors-null", () => Old(new CsProperty(Cs.Int, "P") { Accessors = null! }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "invalid: GEN002 Required node or collection is null.");
        yield return new("feature.interface-property-null-accessor", () => Old(new CsProperty(Cs.Int, "P") { Accessors = new CsAccessor[] { null! } }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "invalid: GEN002 Required node or collection is null.");
        yield return new("feature.interface-event-old", () => Old(new CsEvent("System.Action", "E") { Accessors = new[] { new CsAccessor("add") { Body = Cs.Body() }, new CsAccessor("remove") { Body = Cs.Body() } } }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "invalid: GEN073 Implemented/private/static interface member requires C# 8.");
        yield return new("feature.interface-event-accessors-null", () => Old(new CsEvent("System.Action", "E") { Accessors = null! }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "invalid: GEN002 Required node or collection is null.");
        yield return new("feature.interface-event", () => Old(new CsEvent("System.Action", "E"), CsLanguageVersion.CSharp7_3, TypeKind.Interface), "interface C\n{\n    event System.Action E;\n}\n");
        yield return new("feature.interface-field", () => Old(new CsField(Cs.Int, "F") { Modifiers = new[] { "const" }, Initializer = Cs.Literal(1) }, CsLanguageVersion.CSharp7_3, TypeKind.Interface), "interface C\n{\n    const int F = 1;\n}\n");
        yield return new("feature.interface-private-old", () => Old(M("private"), CsLanguageVersion.CSharp7_3, TypeKind.Interface), "invalid: GEN073 Implemented/private/static interface member requires C# 8.");
        yield return new("feature.interface-static-abstract-old", () => Old(new CsMethod(Cs.Void, "M") { Modifiers = new[] { "static", "abstract" } }, CsLanguageVersion.CSharp10, TypeKind.Interface), "invalid: GEN073 Static abstract/virtual interface member requires C# 11.");
        yield return new("feature.interface-static-virtual-old", () => Old(M("static", "virtual"), CsLanguageVersion.CSharp10, TypeKind.Interface), "invalid: GEN073 Static abstract/virtual interface member requires C# 11.");
        yield return new("feature.struct-constructor-old", () => Old(new CsConstructor("C"), CsLanguageVersion.CSharp9, TypeKind.Struct), "invalid: GEN073 Parameterless struct constructor requires C# 10.");
        yield return new("feature.struct-constructor-parameters-null", () => Old(new CsConstructor("C") { Parameters = null! }, CsLanguageVersion.CSharp9, TypeKind.Struct), "invalid: GEN002 Required node or collection is null.");
        yield return new("feature.struct-static-constructor", () => Old(new CsConstructor("C") { Modifiers = new[] { "static" } }, CsLanguageVersion.CSharp9, TypeKind.Struct), "struct C\n{\n    static C()\n    {\n    }\n}\n");
        yield return new("feature.record-struct-constructor-old", () => Old(new CsConstructor("C") { Parameters = new[] { new CsParameter(Cs.Int, "x") } }, CsLanguageVersion.CSharp10, TypeKind.RecordStruct), "record struct C\n{\n    C(int x)\n    {\n    }\n}\n");
        yield return new("feature.struct-field-initializer-old", () => Old(new CsField(Cs.Int, "F") { Initializer = Cs.Literal(1) }, CsLanguageVersion.CSharp9, TypeKind.Struct), "invalid: GEN073 Struct instance initializer requires C# 10.");
        yield return new("feature.struct-static-field-initializer", () => Old(new CsField(Cs.Int, "F") { Modifiers = new[] { "static" }, Initializer = Cs.Literal(1) }, CsLanguageVersion.CSharp9, TypeKind.Struct), "struct C\n{\n    static int F = 1;\n}\n");
        yield return new("feature.struct-property-initializer-old", () => Old(new CsProperty(Cs.Int, "P") { Accessors = new[] { new CsAccessor("get") }, Initializer = Cs.Literal(1) }, CsLanguageVersion.CSharp9, TypeKind.Struct), "invalid: GEN073 Struct instance initializer requires C# 10.");
        yield return new("feature.scoped-parameter-old", () => InClass(new CsMethod(Cs.Void, "M") { Parameters = new[] { new CsParameter(Cs.Type("System.Span").Generic(Cs.Int), "s") { Modifier = "scoped" } }, Body = Cs.Body() }).At(CsLanguageVersion.CSharp10), "invalid: GEN073 Scoped parameter requires C# 11.");
        yield return new("feature.params-collection-old", () => InClass(new CsMethod(Cs.Void, "M") { Parameters = new[] { new CsParameter(Cs.Type("System.Span").Generic(Cs.Int), "s") { Modifier = "params" }, }, Body = Cs.Body() }).At(CsLanguageVersion.CSharp12), "invalid: GEN073 Params collection requires C# 13.");
        yield return new("feature.params-raw", () => InClass(new CsMethod(Cs.Void, "M") { Parameters = new[] { new CsParameter(Cs.RawType("int[]"), "s") { Modifier = "params" }, }, Body = Cs.Body() }).At(CsLanguageVersion.CSharp12), "class C\n{\n    void M(params int[] s)\n    {\n    }\n}\n");
        yield return new("feature.params-untyped", () => InClass(new CsMethod(Cs.Void, "M") { Parameters = new[] { new CsParameter(null, "s") { Modifier = "params" }, }, Body = Cs.Body() }), "invalid: GEN002 Required node or collection is null.");

        // Modifier rules and conflicts.
        yield return new("modifier.protected-internal", () => InClass(M("protected", "internal")), "class C\n{\n    protected internal void M()\n    {\n    }\n}\n");
        yield return new("modifier.private-protected", () => InClass(M("private", "protected")), "class C\n{\n    protected private void M()\n    {\n    }\n}\n");
        yield return new("modifier.protected-public", () => InClass(M("protected", "public")), "invalid: GEN033 Conflicting accessibility modifiers.");
        yield return new("modifier.three-access", () => InClass(M("protected", "internal", "private")), "invalid: GEN033 Conflicting accessibility modifiers.");
        yield return new("modifier.abstract-sealed", () => InClass(M("abstract", "sealed", "override") with { Body = null }), "invalid: GEN034 Conflicting modifiers.");
        yield return new("modifier.abstract-static", () => InClass(M("abstract", "static") with { Body = null }), "invalid: GEN034 Conflicting modifiers.");
        yield return new("modifier.abstract-virtual", () => InClass(M("abstract", "virtual") with { Body = null }), "invalid: GEN034 Conflicting modifiers.");
        yield return new("modifier.static-virtual", () => InClass(M("static", "virtual")), "invalid: GEN034 Conflicting modifiers.");
        yield return new("modifier.static-override", () => InClass(M("static", "override")), "invalid: GEN034 Conflicting modifiers.");
        yield return new("modifier.virtual-override", () => InClass(M("virtual", "override")), "invalid: GEN034 Conflicting modifiers.");
        yield return new("modifier.interface-static-abstract", () => InType(TypeKind.Interface, M("static", "abstract") with { Body = null }), "interface C\n{\n    static abstract void M();\n}\n");
        yield return new("modifier.interface-static-virtual", () => InType(TypeKind.Interface, M("static", "virtual")), "interface C\n{\n    static virtual void M()\n    {\n    }\n}\n");
        yield return new("modifier.const-static", () => InClass(new CsField(Cs.Int, "F") { Modifiers = new[] { "const", "static" }, Initializer = Cs.Literal(1) }), "invalid: GEN048 Invalid constant/readonly/volatile field combination.");
        yield return new("modifier.const-volatile", () => InClass(new CsField(Cs.Int, "F") { Modifiers = new[] { "const", "volatile" }, Initializer = Cs.Literal(1) }), "invalid: GEN048 Invalid constant/readonly/volatile field combination.");
        yield return new("modifier.readonly-volatile", () => InClass(new CsField(Cs.Int, "F") { Modifiers = new[] { "readonly", "volatile" } }), "invalid: GEN048 Invalid constant/readonly/volatile field combination.");
        yield return new("modifier.static-constructor-parameters", () => InClass(new CsConstructor("C") { Modifiers = new[] { "static" }, Parameters = new[] { new CsParameter(Cs.Int, "x") } }), "invalid: GEN053 Static constructor cannot have accessibility, parameters, or initializer.");
        yield return new("modifier.static-constructor-initializer", () => InClass(new CsConstructor("C") { Modifiers = new[] { "static" }, InitializerKind = "this" }), "invalid: GEN053 Static constructor cannot have accessibility, parameters, or initializer.");
        yield return new("modifier.static-constructor-parameters-null", () => InClass(new CsConstructor("C") { Modifiers = new[] { "static" }, Parameters = null! }), "invalid: GEN002 Required node or collection is null.");
        yield return new("modifier.delegate", () => new CsDocument { Items = new CsNode[] { new CsDelegate(Cs.Void, "D") { Modifiers = new[] { "public", "static" } } } }, "invalid: GEN031 Modifier 'static' is not valid for this construct.");
        yield return new("modifier.destructor", () => InClass(new CsDestructor("C", Cs.Body()) { Modifiers = new[] { "public" } }), "invalid: GEN031 Modifier 'public' is not valid for this construct.");
        yield return new("modifier.operator", () => InClass(new CsOperatorDeclaration(OverloadableOperator.Plus, Cs.Type("C")) { Modifiers = new[] { "public", "static", "override" }, Parameters = new[] { new CsParameter(Cs.Type("C"), "a"), new CsParameter(Cs.Type("C"), "b") }, Body = Cs.Body(Cs.Return(Cs.Id("a"))) }), "invalid: GEN031 Modifier 'override' is not valid for this construct. | GEN034 Conflicting modifiers.");
        yield return new("modifier.extension", () => new CsDocument { Types = new[] { new CsTypeDeclaration(TypeKind.Class, "E") { Modifiers = new[] { "static" }, Members = new CsMember[] { new CsExtension(Cs.Type("string"), "s") { Modifiers = new[] { "public" } } } } } }, "invalid: GEN031 Modifier 'public' is not valid for this construct.");
        yield return new("modifier.event", () => InClass(new CsEvent("System.Action", "E") { Modifiers = new[] { "required" } }), "invalid: GEN031 Modifier 'required' is not valid for this construct.");
        yield return new("modifier.foreign", () => InClass(new ForeignMember() { Modifiers = new[] { "public" } }), "invalid: GEN031 Modifier 'public' is not valid for this construct. | GEN055 Unsupported member node.");
        yield return new("modifier.variable-unknown", () => InMethod(Cs.Local(Cs.Int, "x", Cs.Literal(1)) with { VariableModifiers = (CsVariableModifiers)64 }), "invalid: GEN092 Incompatible variable modifiers.");
        yield return new("modifier.variable-readonly", () => InMethod(Cs.Local(Cs.Int, "x", Cs.Literal(1)) with { VariableModifiers = CsVariableModifiers.ReadOnly }), "invalid: GEN092 Incompatible variable modifiers.");
        yield return new("modifier.variable-ref-readonly", () => InMethod(Cs.Local(Cs.Int, "x", Cs.Id("y")) with { VariableModifiers = CsVariableModifiers.Ref | CsVariableModifiers.ReadOnly }), "class C\n{\n    void M()\n    {\n        ref readonly int x = y;\n    }\n}\n");
        yield return new("modifier.variable-const-var", () => InMethod(Cs.Var("x", Cs.Literal(1)) with { VariableModifiers = CsVariableModifiers.Const }), "invalid: GEN092 Incompatible variable modifiers.");
        yield return new("modifier.variable-const-ref", () => InMethod(Cs.Local(Cs.Int, "x", Cs.Literal(1)) with { VariableModifiers = CsVariableModifiers.Const | CsVariableModifiers.Ref }), "invalid: GEN092 Incompatible variable modifiers.");
        yield return new("modifier.variable-const-foreach", () => InMethod(Cs.ForEach(Cs.Int, "x", Id, Cs.Body()) with { VariableModifiers = CsVariableModifiers.Const }), "invalid: GEN092 Incompatible variable modifiers.");
        yield return new("modifier.variable-scoped-old", () => InMethod(Cs.Local(Cs.Type("System.Span").Generic(Cs.Int), "x", Cs.Id("y")) with { VariableModifiers = CsVariableModifiers.Scoped }).At(CsLanguageVersion.CSharp10), "invalid: GEN073 Scoped variable requires C# 11.");

        // Member validator corners.
        yield return new("member.operator-null-return", () => InClass(new CsOperatorDeclaration(OverloadableOperator.Multiply, null!) { Modifiers = new[] { "public", "static" }, Parameters = new[] { new CsParameter(Cs.Type("C"), "a"), new CsParameter(Cs.Type("C"), "b") }, Body = Cs.Body() }), "invalid: GEN002 Required node or collection is null.");
        yield return new("member.compound-null-return", () => InClass(new CsOperatorDeclaration(OverloadableOperator.AddAssign, null!) { Modifiers = new[] { "public" }, Parameters = new[] { new CsParameter(Cs.Int, "x") }, Body = Cs.Body() }), "invalid: GEN002 Required node or collection is null. | GEN092 Instance mutation operator has an invalid signature.");
